class estadisticaActions extends sfActions
{
	public function executeIndex()
	{
		return $this->forward('estadistica', 'list');
	}

    public function verificaPrilegio($currentForm)
	{ 
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		if(!$this->getUser()->checkPerm($currentForm, $usuariologuiado)){
			$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
		}
		
	}
	public function verificaPrilegioCerrar($currentForm)
	{ 
		$usuarioLoguiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		if(!$this->getUser()->checkPerm($currentForm, $usuarioLoguiado)){
			$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
		}
			
	}
	
	public function executeConsulta()
	{ 
		$this->estadistica = new Estadistica();
	}

	public function executeList()
	{ 
		$this->verificaPrilegio("estadistica/list");
		$c=new Criteria();	 
		$c->setDistinct();  
		$this->parametros="&a=1";
		$usuariologuiado=$this->getUser()->getAttribute('usuario_id','', 'subscriber');
		
		
		if($this->getRequestParameter('modulo')){
			
			$c->add(EstadisticaPeer::MODULO,'%'.$this->getRequestParameter('modulo').'%',Criteria::LIKE);	
			$this->parametros.="&modulo=".$this->getRequestParameter('modulo');	
							
		}
		
		if($this->getRequestParameter('nombre')){
			
			$c->add(EstadisticaPeer::NOMBRE,'%'.$this->getRequestParameter('nombre').'%',Criteria::LIKE);	
			$this->parametros.="&nombre=".$this->getRequestParameter('nombre');	
							
		}
		
		if($this->getRequestParameter('descripcion')){
			
			$c->add(EstadisticaPeer::DESCRIPCION,'%'.$this->getRequestParameter('descripcion').'%',Criteria::LIKE);	
			$this->parametros.="&descripcion=".$this->getRequestParameter('descripcion');	
							
		}
		
		if($this->getRequestParameter('fecha_inicial')){
			
			$this->fecha_inicial=$this->getRequestParameter('fecha_inicial');	
			$this->parametros.="&fecha_inicial=".str_replace("/","-",$this->getRequestParameter('fecha_inicial'));
			
							
		}
		if($this->getRequestParameter('fecha_final')){
			
			$this->fecha_final=$this->getRequestParameter('fecha_final');
			$this->parametros.="&fecha_final=".str_replace("/","-",$this->getRequestParameter('fecha_final'));		
							
		}
		
		if($this->getRequestParameter('orden')){
			$c->addDescendingOrderByColumn(EstadisticaPeer::$this->getRequestParameter('orden'));		
			$this->parametros.="&orden=".$this->getRequestParameter('orden');			 	
		}
		else{
			$c->addDescendingOrderByColumn(EstadisticaPeer::ORDEN);
		}
		
		$pager=new sfPropelPager('Estadistica',10);
		$pager->setCriteria($c);
		$pager->setPage($this->getRequestParameter('page',1));
		$pager->init();
		$this->pager=$pager;   
		$this->controlPaginacion = 1;	
		
		$i=0; 
		$this->cantidad=array();
		//echo count($pager->getResults());
		//exit;
		$fecha_inicial_consulta = $this->getRequestParameter('fecha_inicial');
		$fecha_final_consulta   = $this->getRequestParameter('fecha_final');
		foreach ($pager->getResults() as $estadistica){	   
		$this->cantidad[$i]= EstadisticaPeer::getCantidad($estadistica->getCodigosql(),$fecha_inicial_consulta,$fecha_final_consulta);	   
		$i++; 
		}	
	}

	public function executeExcel()
	{ 
		$c=new Criteria();	 
		$c->setDistinct();  
		$this->parametros="a=1";
		$this->fecha_inicial = "";
		$this->fecha_final = "";
		
		$usuariologuiado=$this->getUser()->getAttribute('usuario_id','', 'subscriber');
			
		if($this->getRequestParameter('modulo')){
			$c->add(EstadisticaPeer::MODULO,'%'.$this->getRequestParameter('modulo').'%',Criteria::LIKE);	
			$this->parametros.="&modulo=".$this->getRequestParameter('modulo');
		}
		
		if($this->getRequestParameter('nombre')){	    
			$c->add(EstadisticaPeer::NOMBRE,'%'.$this->getRequestParameter('nombre').'%',Criteria::LIKE);	
			$this->parametros.="&nombre=".$this->getRequestParameter('nombre');
		}
		
		if($this->getRequestParameter('descripcion')){	    
			$c->add(EstadisticaPeer::DESCRIPCION,'%'.$this->getRequestParameter('descripcion').'%',Criteria::LIKE);	
			$this->parametros.="&descripcion=".$this->getRequestParameter('descripcion');
		}
		
		if($this->getRequestParameter('fecha_inicial')){	    
			$this->fecha_inicial = $this->getRequestParameter('fecha_inicial');
			$this->parametros.="&fecha_inicial=".$this->getRequestParameter('fecha_inicial');
		}
		
		if($this->getRequestParameter('fecha_final')){	    
			$this->fecha_final=$this->getRequestParameter('fecha_final');
			$this->parametros.="&fecha_final=".$this->getRequestParameter('fecha_final');						 	
		}	
		
		if($this->getRequestParameter('orden')){
			$c->addDescendingOrderByColumn(EstadisticaPeer::$this->getRequestParameter('orden'));		
			$this->parametros.="&orden=".$this->getRequestParameter('orden');			 	
		}else{
			$c->addAscendingOrderByColumn(EstadisticaPeer::ORDEN);
		}
		
		$c->clearSelectColumns();//limpiamos la clausula select        
		//adicionamos las columnas que nesesitamos
		$c->addSelectColumn(EstadisticaPeer::ESTADISTICA_ID);//0
		$c->addSelectColumn(EstadisticaPeer::ORDEN);//1
		$c->addSelectColumn(EstadisticaPeer::MODULO);//2        
		$c->addSelectColumn(EstadisticaPeer::NOMBRE);//3
		$c->addSelectColumn(EstadisticaPeer::DESCRIPCION);//4
		$c->addSelectColumn(EstadisticaPeer::CODIGOSQL);//5
		$this->resultset = EstadisticaPeer::doSelectStmt($c);
		//**************************************************************************************
		$this->setLayout(false);
	}

	public function executeShow()
	{
		$this->estadistica = EstadisticaPeer::retrieveByPk($this->getRequestParameter('estadistica_id'));
		$this->forward404Unless($this->estadistica);
	}

	public function executeCreate()
	{
		$this->estadistica = new Estadistica();

		$this->setTemplate('edit');
	}

	public function executeEdit()
	{
		$this->estadistica = EstadisticaPeer::retrieveByPk($this->getRequestParameter('estadistica_id'));
		$this->forward404Unless($this->estadistica);
	}

	public function executeUpdate()
	{
		if (!$this->getRequestParameter('estadistica_id'))
		{
		$estadistica = new Estadistica();
		}
		else
		{
		$estadistica = EstadisticaPeer::retrieveByPk($this->getRequestParameter('estadistica_id'));
		$this->forward404Unless($estadistica);
		}

		//$estadistica->setEstadisticaId($this->getRequestParameter('estadistica_id'));
		$estadistica->setOrden($this->getRequestParameter('orden'));
		$estadistica->setModulo($this->getRequestParameter('modulo'));
		$estadistica->setNombre($this->getRequestParameter('nombre'));
		$estadistica->setDescripcion($this->getRequestParameter('descripcion'));
		$estadistica->setCodigosql($this->getRequestParameter('codigosql'));

		$estadistica->save();

		return $this->redirect($this->getRequest()->getScriptName().'/estadistica/show?estadistica_id='.$estadistica->getEstadisticaId());
	}

	public function executeDelete()
	{
		$estadistica = EstadisticaPeer::retrieveByPk($this->getRequestParameter('estadistica_id'));

		$this->forward404Unless($estadistica);

		$estadistica->delete();

		return $this->redirect($this->getRequest()->getScriptName().'/estadistica/list');
	}
}
